  function moonInfo(degrees){const longitude=angular(degrees),sign=Math.floor(longitude/30),nak=Math.min(26,Math.floor(longitude*3/40+1e-12));return {longitude,sign,signName:SIGNS[sign],signLord:SIGN_LORDS[sign],degree:longitude%30,nakshatra:nak+1,nakshatraName:STARS[nak],pada:Math.min(107,Math.floor(longitude*3/10+1e-12))%4+1,varna:VARNA[sign],vashya:vashya(longitude),gana:GANA[nak],yoni:YONI_MAP[nak],nadi:NADI[nak]};}
  function vashya(longitude){const sign=Math.floor(longitude/30),degree=longitude%30;if([0,1].includes(sign)||sign===8&&degree>=15||sign===9&&degree<15)return 0;if([2,5,6,10].includes(sign)||sign===8&&degree<15)return 1;if([3,11].includes(sign)||sign===9&&degree>=15)return 2;return sign===4?3:4;}
