  function dateValid(text){if(!/^\d{4}-\d{2}-\d{2}$/.test(text))return false;const d=new Date(text+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===text&&d.getUTCFullYear()>=1900&&d.getUTCFullYear()<=2100;}
  function validRecord(r){return plain(r)&&PROFILE_FIELDS.every(k=>typeof r[k]==='string')&&r.name.length<=120&&r.place.length<=120&&dateValid(r.date)&&/^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(r.time)&&['timezone','dst','latitude','longitude'].every(k=>r[k].trim()!==''&&Number.isFinite(Number(r[k])))&&Math.abs(Number(r.timezone))<=14&&Math.abs(Number(r.dst))<=180&&Math.abs(Number(r.latitude))<90&&Math.abs(Number(r.longitude))<=180&&Math.abs(Number(r.timezone)+Number(r.dst)/60)<=14;}
