  function validSettings(s){return plain(s)&&Object.hasOwn(REGIONS,s.region)&&Array.isArray(s.bases)&&s.bases.length>=1&&s.bases.length<=3&&new Set(s.bases).size===s.bases.length&&s.bases.every(b=>BASES.includes(b));}
